-- Version the exact guest-safe public QR RPCs already verified in the live BrewOS database.
-- Menu responses expose only guest-facing item fields, never preparation costs.
-- Table lookup requires the full QR token and returns only public venue/branch/table labels.

CREATE OR REPLACE FUNCTION public.get_public_cafe_menu(p_slug text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
      'id', c.id,
          'name', c.name,
              'description', c.description,
                  'logo_url', c.logo_url,
                      'branch', (
                            select jsonb_build_object(
                                    'id', b.id,
                                            'name', b.name,
                                                    'address', b.address
                                                          )
                                                                from public.branches b
                                                                      where b.cafe_id = c.id
                                                                              and b.active = true
                                                                                    order by b.created_at asc
                                                                                          limit 1
                                                                                              ),
                                                                                                  'categories', coalesce((
                                                                                                        select jsonb_agg(
                                                                                                                jsonb_build_object(
                                                                                                                          'id', mc.id,
                                                                                                                                    'name', mc.name,
                                                                                                                                              'items', (
                                                                                                                                                          select coalesce(jsonb_agg(
                                                                                                                                                                        jsonb_build_object(
                                                                                                                                                                                        'id', mi.id,
                                                                                                                                                                                                        'name', mi.name,
                                                                                                                                                                                                                        'description', mi.description,
                                                                                                                                                                                                                                        'image_url', mi.image_url,
                                                                                                                                                                                                                                                        'price_paise', mi.price_paise
                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                    order by mi.sort_order, mi.name
                                                                                                                                                                                                                                                                                                ), '[]'::jsonb)
                                                                                                                                                                                                                                                                                                            from public.menu_items mi
                                                                                                                                                                                                                                                                                                                        where mi.category_id = mc.id
                                                                                                                                                                                                                                                                                                                                      and mi.cafe_id = c.id
                                                                                                                                                                                                                                                                                                                                                    and mi.is_available = true
                                                                                                                                                                                                                                                                                                                                                                  and (
                                                                                                                                                                                                                                                                                                                                                                                  mi.branch_id is null
                                                                                                                                                                                                                                                                                                                                                                                                  or mi.branch_id = (
                                                                                                                                                                                                                                                                                                                                                                                                                    select b.id
                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.branches b
                                                                                                                                                                                                                                                                                                                                                                                                                                                        where b.cafe_id = c.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and b.active = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              order by b.created_at asc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                limit 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        order by mc.sort_order, mc.name
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    from public.menu_categories mc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where mc.cafe_id = c.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  and mc.active = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mc.branch_id is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              or mc.branch_id = (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          select b.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.branches b
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where b.cafe_id = c.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                and b.active = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            order by b.created_at asc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        limit 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ), '[]'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from public.cafes c
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where c.slug = lower(trim(p_slug))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        and c.status = 'approved'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          limit 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          $function$;

revoke all on function public.get_public_cafe_menu(text) from public;
grant execute on function public.get_public_cafe_menu(text) to anon, authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_public_table_info(p_token text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT pg_catalog.jsonb_build_object(
      'restaurant_name', c.name,
          'branch_name', b.name,
              'table_name', t.table_name
                )
                  FROM public.dining_tables AS t
                    JOIN public.cafes AS c ON c.id = t.cafe_id
                      JOIN public.branches AS b
                          ON b.id = t.branch_id
                             AND b.cafe_id = t.cafe_id
                               WHERE p_token ~ '^[0-9a-fA-F]{64}$'
                                   AND t.qr_token_hash =
                                         pg_catalog.encode(
                                                 extensions.digest(p_token, 'sha256'),
                                                         'hex'
                                                               )
                                                                   AND t.active = true
                                                                       AND b.active = true
                                                                           AND c.status = 'approved'
                                                                             LIMIT 1;
                                                                             $function$;

revoke all on function public.get_public_table_info(text) from public;
grant execute on function public.get_public_table_info(text) to anon, authenticated, service_role;
